/** As-authored tone most of the time; soft and deep are the variations. */
const shadeWeights = [
	2,
	5,
	2
];
/** Most guys keep the feet their head was drawn with. */
const footWeights = [
	5,
	2,
	2,
	1
];
/** Patterns usually use the pattern colour; the accent is the alternate. */
const patternToneWeights = [3, 1];
/** No palette is more "correct" than another. */
const paletteWeights = new Array(32).fill(1);
/**
* Picks an index from a weight table using a hash value, so the result is
* deterministic for a given input and the distribution follows the weights.
*/
function weightedPick(weights, hashValue) {
	let total = 0;
	for (const w of weights) total += w;
	let remaining = hashValue % total;
	for (let i = 0; i < weights.length; i++) {
		remaining -= weights[i];
		if (remaining < 0) return i;
	}
	return weights.length - 1;
}

//#endregion
//#region src/resolve.ts
/**
* Resolves an input string to a full AvatarConfig.
*
* Each slot is hashed independently so adding or removing variants from one
* part doesn't cascade into the others, and each pick is weighted (see
* ./parts/weights) so the set keeps its character as the library grows —
* a uniform roll over a big library averages out to something bland.
*/
function resolve(input, overrides) {
	const pick = (slotIndex, weights) => weightedPick(weights, hashNth(input, slotIndex));
	return {
		head: overrides?.head ?? pick(0, headWeights),
		eyes: overrides?.eyes ?? pick(1, eyeWeights),
		mouth: overrides?.mouth ?? pick(2, mouthWeights),
		hair: overrides?.hair ?? pick(3, hairWeights),
		body: overrides?.body ?? pick(4, bodyWeights),
		accessory: overrides?.accessory ?? pick(5, accessoryWeights),
		palette: pick(6, paletteWeights),
		rotation: hashNth(input, 7) % 9,
		flip: overrides?.flip ?? hashNth(input, 8) % 2 === 1,
		shade: overrides?.shade ?? weightedPick(shadeWeights, hashNth(input, 9)),
		feet: overrides?.feet ?? weightedPick(footWeights, hashNth(input, 10)),
		patternTone: overrides?.patternTone ?? weightedPick(patternToneWeights, hashNth(input, 11))
	};
}

//#endregion
//#region src/v2/resolve.ts
/**
* Resolves a name to a v2 config — and it is v1's resolve, untouched.
*
* Same hash, same weights, and it only ever rolls over v1's parts, so a
* name-drawn guy is the same guy on v2 as he was on v1. New parts reach a
* character only when the player picks them; the new slots start empty.
*/
function resolveV2(input, overrides) {
	const config = {
		...resolve(input, overrides),
		outfit: overrides?.outfit ?? 0,
		held: overrides?.held ?? 0,
		backdrop: overrides?.backdrop ?? 0
	};
	if (overrides?.tints) config.tints = overrides.tints;
	return config;
}

